0 & a_{22} & \cdots & a_{2 n} \\
\vdots & \vdots & & \vdots \\
0 & 0 & \cdots & a_{n n}
\end{array}\right|=a_{11}\left|\begin{array}{cccc}
a_{22} & a_{23} & \cdots & a_{2 n} \\
0 & a_{33} & \cdots & a_{3 n} \\
\vdots & \vdots & & \vdots \\
0 & 0 & \cdots & a_{n n}
\end{array}\right| \\
& =\cdots=a_{11} \cdot a_{22} \cdots a_{n n} .
\end{aligned}
\]
